for i in range(int(input())):
	a = int(input())
	l = list(map(int, input().split(' ')))
	l1 = [-1 for i in range(a)]
	l1[-1] = 1
	for i in range(a - 2, -1, -1):
		if l[i] >= 0 and l[i + 1] <= 0 or (l[i] <= 0 and l[i + 1] >= 0):
			l1[i] = l1[i + 1] + 1
		else:
			l1[i] = 1
	for i in l1:
		print(i, end=' ')
	print()
